{
  "appearance_facts": [
    {
      "location": "A single blue line spans the plot from the left edge near x=270 to the right edge near x=2100, rising overall from y~1180 to y~420.",
      "fact": "The line starts flat, climbs steadily through the middle years, dips briefly around 1888, then climbs sharply to the right edge."
    },
    {
      "location": "Left segment from 1880 to 1881 (x~270 to x~390).",
      "fact": "The line is nearly horizontal at a low level, around the 1,000-1,100 gridline region."
    },
    {
      "location": "Middle segment from 1882 to 1885 (x~510 to x~1110).",
      "fact": "The line rises continuously from about the 1,300 level to just under the 2,000 gridline."
    },
    {
      "location": "Segment from 1886 to 1888 (x~1230 to x~1590).",
      "fact": "The line reaches a local peak near 2,500 at 1887, then drops to a local trough near 2,300 at 1888."
    },
    {
      "location": "Right segment from 1889 to 1891 (x~1710 to x~2100).",
      "fact": "The line climbs steeply, passing the 2,500 gridline at 1889, the 3,000 gridline at 1890, and ending above 3,000 near 3,200 at 1891."
    }
  ],
  "printed_facts": [
    {
      "location": "Chart title at top center.",
      "fact": "Title reads 'Decreasing Number of New Tourists in Town Z from 1880 to 1891'."
    },
    {
      "location": "Vertical axis label, rotated, at left.",
      "fact": "Y-axis is labeled 'Number of Tourists'."
    },
    {
      "location": "Horizontal axis label at bottom center.",
      "fact": "X-axis is labeled 'Year'."
    },
    {
      "location": "Y-axis tick labels from bottom to top.",
      "fact": "Ticks are 0, 500, 1,000, 1,500, 2,000, 2,500, 3,000, 3,500."
    },
    {
      "location": "X-axis tick labels from left to right.",
      "fact": "Ticks are 1880, 1881, 1882, 1883, 1884, 1885, 1886, 1887, 1888, 1889, 1890, 1891."
    },
    {
      "location": "Line value at 1880 (leftmost point).",
      "fact": "Approximately 1,100 new tourists."
    },
    {
      "location": "Line value at 1885.",
      "fact": "Approximately 1,900 new tourists, just below the 2,000 gridline."
    },
    {
      "location": "Line value at 1887 (local peak).",
      "fact": "Approximately 2,450-2,500 new tourists."
    }
  ],
  "public_definitions": [],
  "uncertain": [
    "The chart title states 'Decreasing Number of New Tourists', but the plotted line shows an overall increasing trend from 1880 to 1891; the title and the data geometry disagree.",
    "Exact numeric values at each year are not labeled on the line, so readings are estimated from gridline positions."
  ]
}
